const root = $json.body || $json || {};
const payload = root.raw_payload || root.data || root.payload || root;
const key = payload.key || root.key || payload.message?.key || {};
const msgObj = payload.message || root.message || payload.messages?.[0]?.message || root.messages?.[0]?.message || {};

function firstString(...values) {
  for (const value of values) {
    if (value === null || value === undefined) continue;
    if (typeof value === 'string' || typeof value === 'number') {
      const text = String(value).trim();
      if (text) return text;
    }
  }
  return '';
}

function dig(obj, path) {
  return path.split('.').reduce((acc, part) => acc && acc[part] !== undefined ? acc[part] : undefined, obj);
}

let chatId = firstString(
  root.chat_id, root.chatId, root.chat,
  payload.chat_id, payload.chatId, payload.chat,
  key.remoteJid, payload.remoteJid, payload.from, root.from,
  dig(payload, 'sender.id'), dig(root, 'sender.id')
);

let senderId = firstString(
  root.sender_id, root.senderId, root.sender,
  payload.sender_id, payload.senderId, payload.sender,
  key.participant, payload.participant,
  root.participant,
  chatId
);

if (!chatId && senderId) chatId = senderId;
if (!senderId && chatId) senderId = chatId;

const messageText = firstString(
  root.userMessage, root.content, root.body, root.text, root.messageText,
  payload.userMessage, payload.content, payload.body, payload.text, payload.messageText,
  msgObj.conversation,
  dig(msgObj, 'extendedTextMessage.text'),
  dig(msgObj, 'imageMessage.caption'),
  dig(msgObj, 'videoMessage.caption'),
  dig(msgObj, 'documentMessage.caption'),
  dig(msgObj, 'buttonsResponseMessage.selectedDisplayText'),
  dig(msgObj, 'listResponseMessage.title'),
  dig(msgObj, 'templateButtonReplyMessage.selectedDisplayText')
);

let normalizedTimestamp = new Date().toISOString();
const rawTimestamp = firstString(
  root.timestamp, payload.timestamp, payload.ts, payload.created_at, payload.messageTimestamp, root.messageTimestamp
);
if (rawTimestamp) {
  const asNumber = Number(rawTimestamp);
  const parsed = Number.isFinite(asNumber)
    ? new Date(asNumber < 1000000000000 ? asNumber * 1000 : asNumber)
    : new Date(rawTimestamp);
  if (!Number.isNaN(parsed.getTime())) normalizedTimestamp = parsed.toISOString();
}

const isGroupChat = String(chatId).includes('@g.us');
const chatType = isGroupChat ? 'group' : 'private';
const rawWhatsapp = firstString(
  root.whatsapp_number, root.whatsappNumber,
  payload.whatsapp_number, payload.whatsappNumber,
  isGroupChat ? senderId : chatId,
  senderId,
  chatId
);

function normalizeIdentity(value) {
  const raw = String(value || '')
    .replace(/@c\.us$/i, '')
    .replace(/@s\.whatsapp\.net$/i, '')
    .replace(/@lid(\.whatsapp\.net)?$/i, '')
    .replace(/@g\.us$/i, '')
    .trim();
  const digits = raw.replace(/\D/g, '');
  if (digits) return digits;
  return raw.replace(/[^a-z0-9_\-]/gi, '').slice(0, 64);
}

let whatsappNumber = normalizeIdentity(rawWhatsapp);
if (!whatsappNumber) whatsappNumber = normalizeIdentity(senderId || chatId) || `unknown_${Date.now()}`;
if (!chatId) chatId = `${whatsappNumber}@s.whatsapp.net`;
if (!senderId) senderId = chatId;

const STEPUP_CLIENT_ID = 'd4c5656e-836f-4abf-87ff-6cc7d3de5c1c';
const clientId = firstString(root.client_id, root.clientId, payload.client_id, payload.clientId) || STEPUP_CLIENT_ID;
const sessionName = firstString(root.session_name, root.session, payload.session_name, payload.session, payload.instance, payload.account, root.instance) || 'Tab';

return {
  chat_id: chatId,
  sender_id: senderId,
  userMessage: messageText,
  timestamp: normalizedTimestamp,
  chat_type: chatType,
  whatsapp_number: whatsappNumber,
  client_id: clientId,
  session_name: sessionName,
  incoming_is_valid: !!(chatId && whatsappNumber && messageText)
};

const msg = $('Normalize Incoming Message').first().json;
const leadRow = ($input.first() && $input.first().json) ? $input.first().json : {};
const hasLead = !!leadRow.id;
const currentState = String(leadRow.current_state || 'IDLE').toUpperCase();
const lastChatRaw = leadRow.last_message_at || leadRow.last_chat_date || null;
let daysSinceLastChat = 0;
if (lastChatRaw) {
  const diff = Date.now() - new Date(lastChatRaw).getTime();
  if (!Number.isNaN(diff) && diff > 0) daysSinceLastChat = Math.floor(diff / 86400000);
}
const staleProcessingSeconds = 180;
let processingAgeSeconds = 0;
if (lastChatRaw) {
  const diffMs = Date.now() - new Date(lastChatRaw).getTime();
  if (!Number.isNaN(diffMs) && diffMs > 0) processingAgeSeconds = Math.floor(diffMs / 1000);
}
const isProcessing = currentState === 'PROCESSING';
const isProcessingExpired = isProcessing && processingAgeSeconds >= staleProcessingSeconds;
const effectiveProcessing = isProcessing && !isProcessingExpired;
return { json: { ...msg, lead_id: hasLead ? leadRow.id : null, current_state: currentState, is_new_lead: !hasLead, is_rechat: hasLead && daysSinceLastChat > 90, is_processing: effectiveProcessing, is_processing_expired: isProcessingExpired, processing_age_seconds: processingAgeSeconds, daysSinceLastChat, previous_last_message_at: lastChatRaw } };

const msg = $json;
const formText = String(msg.userMessage || '').trim();
function extractField(text) {
  const labels = Array.prototype.slice.call(arguments, 1);
  for (const label of labels) {
    const pattern = '(?:^|\\n)\\s*[*_-]*\\s*' + label + '\\s*[:\\-*]?\\s*([^\\n\\r]+)';
    const regex = new RegExp(pattern, 'i');
    const match = text.match(regex);
    if (match && match[1] && match[1].trim()) return match[1].trim();
  }
  return '';
}
const nama = extractField(formText, 'Nama', 'Nama Lengkap');
const domisili = extractField(formText, 'Domisili', 'Kota', 'Lokasi');
const bb = extractField(formText, 'BB', 'Berat Badan', 'Berat');
const tb = extractField(formText, 'TB', 'Tinggi Badan', 'Tinggi');
const goals = extractField(formText, 'Goals', 'Goal', 'Tujuan', 'Goals / Tujuan Fitness');
const alasan = extractField(formText, 'Alasan Join', 'Alasan', 'Reason', 'Alasan Ingin Join');
const isValid = !!(nama && domisili && goals && alasan);
const reminderText = 'Siap Kak, aku bantu proses pendaftarannya ya!\nSebelum mulai, mohon isi data berikut terlebih dahulu agar kami bisa mengenal kebutuhan dan target latihan Kakak dengan lebih baik Ã°Å¸ËœÅ \n\nNama: \nDomisili: \nBerat Badan: \nTinggi Badan: \nGoals: \nAlasan Join: ';
return { json: { whatsapp_number: msg.whatsapp_number, chat_id: msg.chat_id, timestamp: msg.timestamp || new Date().toISOString(), client_id: msg.client_id || 'd4c5656e-836f-4abf-87ff-6cc7d3de5c1c', session_name: msg.session_name || 'Tab', lead_id: msg.lead_id, nama, domisili, bb, tb, goals, alasan, isValid, rawForm: formText, reminderText } };

