function humanClean(text) {
  let out = String(text || '')
    .replace(/\[INTENT:JOIN\]/g, ' [INTENT:JOIN] ')
    .replace(/^#{1,6}\s*/gm, '')
    .replace(/\*\*(.*?)\*\*/g, '$1')
    .replace(/\*(.*?)\*/g, '$1')
    .replace(/__(.*?)__/g, '$1')
    .replace(/_(.*?)_/g, '$1')
    .replace(/[ \t]+$/gm, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

  const bannedCta = /(jika|kalau).*(tertarik|membutuhkan|butuh|ingin tahu|info lebih lanjut)|silakan\s+(tanya|hubungi)|langsung\s+tanya|beritahu\s+ya|kami\s+siap\s+membantu/i;
  out = out
    .split('\n')
    .map(line => line.trim())
    .filter(line => line && !bannedCta.test(line))
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

  return out;
}

function classifyJoinIntent(userText, modelText) {
  const msg = String(userText || '').toLowerCase().trim();
  const modelMarkedJoin = String(modelText || '').includes('[INTENT:JOIN]');

  const registrationPhrases = /(cara daftar|gimana daftar|bagaimana daftar|daftarnya gimana|daftarnya bagaimana|bisa daftar|daftar di sini|daftar disini|langsung daftar|minta form|minta formulir|kirim form|kirim formulir|isi form|isi formulir|mau daftar|ingin daftar|pengen daftar|mau join|ingin join|pengen join|booking sekarang)/i;
  const asksInfo = /(apa saja|apa aja|harga|berapa|biaya|promo|free trial|trial|kelas|program|jadwal|jam|hari|kapan|lokasi|alamat|dimana|fasilitas|coach|special class)/i.test(msg) && !registrationPhrases.test(msg);

  const explicitJoinOnly =
    /(saya|aku|sy|aq)\s*(mau|ingin|pengen)\s*(daftar|join|booking|isi form)\b/i.test(msg) ||
    /^(daftar|join|booking|isi form|mau daftar|mau join)\b/i.test(msg) ||
    /(boleh|bisa)\s*(kirim|isi)\s*(form|formulir)/i.test(msg) ||
    registrationPhrases.test(msg);

  return (modelMarkedJoin || explicitJoinOnly) && explicitJoinOnly && !asksInfo;
}

function hasHallucinationSignals(text, answerMode) {
  const t = String(text || '').toLowerCase();
  if (!t) return true;
  if (/\bzumba\b/i.test(text)) return true;
  if (/\b(database|prompt|assistant|language model|chatgpt|openai)\b/i.test(text)) return true;
  if (answerMode !== 'LOCATION' && /(\balamat\b|\blokasi\b|\[alamat lengkap gym\])/i.test(text)) return true;
  // Instagram hanya hallucination jika bukan mode SOCIAL_MEDIA
  if (answerMode !== 'SOCIAL_MEDIA' && /\bdm instagram\b|hubungi admin resmi|whatsapp atau media sosial/i.test(text)) return true;
  return false;
}

function normalizeRupiahMentions(text) {
  return String(text || '')
    .toLowerCase()
    .replace(/(\d+)\s*jt\b/g, (_, n) => String(Number(n) * 1000000))
    .replace(/(\d+)\s*juta\b/g, (_, n) => String(Number(n) * 1000000))
    .replace(/(\d+)\s*rb\b/g, (_, n) => String(Number(n) * 1000))
    .replace(/(\d+)\s*ribu\b/g, (_, n) => String(Number(n) * 1000));
}

function extractMentionedPrices(text) {
  const normalized = normalizeRupiahMentions(text);
  return [...new Set((normalized.match(/\d{4,9}/g) || [])
    .map(value => Number(value))
    .filter(value => Number.isFinite(value) && value > 0))];
}

function rupiahNumber(value) {
  const numeric = Number(String(value || '').replace(/\D/g, ''));
  return Number.isFinite(numeric) && numeric > 0 ? numeric : null;
}

function packageTokens(name) {
  return String(name || '')
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter(token => token.length >= 4 && !['days', 'challenge', 'program', 'paket', 'class', 'hari', 'fit'].includes(token));
}

function findMatchedPackages(userText, rows) {
  const msg = String(userText || '').toLowerCase();
  const mentionedPrices = extractMentionedPrices(msg);

  return rows
    .map(row => {
      const fullName = String(row.nama_paket || '').toLowerCase();
      if (!fullName) return { row, score: 0 };

      let score = 0;
      if (msg.includes(fullName)) score += 100;

      const rowPrice = rupiahNumber(row.harga);
      if (rowPrice && mentionedPrices.includes(rowPrice)) score += 80;

      const tokens = packageTokens(fullName);
      const matchedTokens = tokens.filter(token => msg.includes(token));
      score += matchedTokens.length * 10;
      if (tokens.length > 0 && matchedTokens.length === tokens.length) score += 25;

      if (/challenge/.test(msg) && /challenge/.test(fullName)) score += 8;
      if (/private/.test(msg) && /private/.test(fullName)) score += 8;
      if (/vip/.test(msg) && /vip/.test(fullName)) score += 8;

      return { row, score };
    })
    .filter(entry => entry.score > 0)
    .sort((a, b) => b.score - a.score || (rupiahNumber(a.row.harga) || 0) - (rupiahNumber(b.row.harga) || 0))
    .map(entry => entry.row);
}

function findMatchedPackage(userText, rows) {
  return findMatchedPackages(userText, rows)[0] || null;
}

function formatPackageDetail(row) {
  const lines = [];
  lines.push(`${row.nama_paket} ya kak:`);
  if (row.fasilitas_utama) lines.push(`Fasilitas: ${row.fasilitas_utama}`);
  if (row.ketentuan) lines.push(`Ketentuan: ${row.ketentuan}`);
  return lines.join('\n');
}

function formatPriceList(rows) {
  const lines = rows.map(r => {
    const harga = String(r.harga || '').trim() || '-';
    const durasi = String(r.durasi || '').trim() || '-';
    const numericHarga = Number(String(harga).replace(/\D/g, ''));
    const hargaText = Number.isFinite(numericHarga) && numericHarga > 0
      ? `Rp${numericHarga.toLocaleString('id-ID')}`
      : harga;
    return `- ${r.nama_paket}: ${hargaText} (${durasi})`;
  });

  return [
    'Ada nih kak, ini pricelist StepUp ya:',
    ...lines,
    'Fasilitas dan ketentuan menyesuaikan paket yang dipilih ya kak 🙂'
  ].join('\n');
}

function formatPackageComparison(rows) {
  const topRows = rows.slice(0, 2);
  const lines = ['Perbedaannya ini ya kak:'];

  topRows.forEach(row => {
    const harga = rupiahNumber(row.harga);
    lines.push(`- ${row.nama_paket} (${harga ? `Rp${harga.toLocaleString('id-ID')}` : (row.harga || '-')}, ${row.durasi || '-'})`);
    if (row.fasilitas_utama) lines.push(`  Fasilitas: ${row.fasilitas_utama}`);
    if (row.ketentuan) lines.push(`  Ketentuan: ${row.ketentuan}`);
  });

  return lines.join('\n');
}

function getGreeting(text) {
  if (/assalamualaikum/i.test(text)) return 'Waalaikumsalam kak, ';
  if (/selamat pagi|pagi|morning/i.test(text)) return 'Pagi kak, ';
  if (/selamat siang|siang/i.test(text)) return 'Siang kak, ';
  if (/selamat sore|sore/i.test(text)) return 'Sore kak, ';
  if (/selamat malam|malam/i.test(text)) return 'Malam kak, ';
  if (/halo|hallo|hello|hi|hey|hai|hei/i.test(text)) return 'Hai kak, ';
  return '';
}

const ctx = $('Build Human WhatsApp Context').first().json;
const answerMode = String(ctx.answerMode || 'GENERAL');
const userText = String(ctx.userMessage || '').trim();
const hasGreetingPrefix = /^(halo|hallo|hello|hi|hey|hai|hei|assalamualaikum|selamat pagi|selamat siang|selamat sore|selamat malam)/i.test(userText);

const allHarga = $('Fetch Sheet Harga').all()
  .map(d => d.json)
  .filter(r => {
    const s = String(r.status || '').toLowerCase();
    return r && r.nama_paket && (!s || s === 'active' || s === 'aktif');
  });

const cleanBase = rawReply || fallbackReply;
let isJoin = classifyJoinIntent(ctx.userMessage, cleanBase);

const asksRegistration = /cara daftar|gimana daftar|bagaimana daftar|daftarnya gimana|daftarnya bagaimana|mau daftar|ingin daftar|pengen daftar|bisa daftar|bisa daftar di sini|bisa daftar disini|daftar di sini|daftar disini|langsung daftar|minta form|minta formulir|kirim form|kirim formulir|mau join|ingin join|pengen join|isi form|formulir/i.test(userText);

if (asksRegistration) {
  isJoin = true;
}

let cleanReply = humanClean(cleanBase).replace('[INTENT:JOIN]', '').trim() || fallbackReply;

if (hasHallucinationSignals(cleanReply, answerMode)) {
  cleanReply = fallbackReply;
}

if (answerMode === 'PRICE_GENERAL_CLARIFY' && allHarga.length > 0) {
  cleanReply = formatPriceList(allHarga);
}

const matchedPackages = findMatchedPackages(userText, allHarga);
const matchedPackage = matchedPackages[0] || null;

if (
  matchedPackage &&
  /fasilitas|ketentuan|include|termasuk|dapat apa|dapet apa|apa aja/i.test(userText)
) {
  cleanReply = formatPackageDetail(matchedPackage);
}

if (
  matchedPackages.length >= 2 &&
  /apa bedanya|bedanya apa|beda apa|beda nya|perbedaannya|perbedaan|compare|bandingkan|vs\b|versus/i.test(userText)
) {
  cleanReply = formatPackageComparison(matchedPackages);
}

if (answerMode !== 'LOCATION') {
  cleanReply = cleanReply
    .split('\n')
    .filter(line => !/(\balamat\b|\blokasi\b|\[alamat lengkap gym\])/i.test(line))
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim() || fallbackReply;
}

if (answerMode === 'SCHEDULE_SPECIFIC_DAY') {
  cleanReply = cleanReply
    .split('\n')
    .filter(line => !/mau dicekkan.*hari apa|cekkan.*hari apa/i.test(line))
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim() || fallbackReply;
}

if (hasGreetingPrefix && cleanReply) {
  const greeting = getGreeting(userText);
  if (greeting && !/^(pagi|siang|sore|malam|hai|halo|hello|hi|waalaikumsalam)/i.test(cleanReply)) {
    cleanReply = greeting + cleanReply.charAt(0).toLowerCase() + cleanReply.slice(1);
  }
}

if (!hasGreetingPrefix && answerMode !== 'GREETING') {
  cleanReply = cleanReply
    .replace(/^(selamat pagi|selamat siang|selamat sore|selamat malam|hai|halo|hello|hi|assalamualaikum|waalaikumsalam)[!,.:\s-]*/i, '')
    .trim();
}

const charLength = cleanReply.length;
let delaySeconds;
if (charLength < 80) delaySeconds = 3;
else if (charLength < 200) delaySeconds = 4;
else if (charLength < 400) delaySeconds = 5;
else delaySeconds = 6;

return {
  json: {
    ...item,
    replyText: cleanReply,
    isJoin,
    joinIntentGuard: isJoin ? 'explicit_join' : 'info_or_unclear',
    hadError: !rawReply,
    errorMessage: rawReply ? '' : 'Model returned empty output',
    delaySeconds,
    chat_id: item.chat_id || ctx.chat_id,
    whatsapp_number: item.whatsapp_number || ctx.whatsapp_number,
    client_id: item.client_id || ctx.client_id,
    session_name: item.session_name || ctx.session_name || 'Tab',
